/**
 * This error is thrown if a promise is known to never terminate.
 */
export class AbandonedData extends Error {
    constructor(message) {
        super(message);
        this.name = "AbandonedData";
    }
}
/**
 * This error is thrown if a field has invalid data that is being accessed
 */
export class DataNotReady extends Error {
    constructor(message) {
        super(message);
        this.name = "DataNotReady";
    }
}
